  v = `İsteğe bağlı: Paketinize oyunlarını eklemek üzere diğer geliştiricileri davet etmeyi seçebilirsiniz. Paketin sahibi olarak diğer geliştiricileri koordine etmek sizin sorumluluğunuzdadır. Ayrıca yine paket sahibi olarak paketi sadece siz Steam mağazasında yayınlayabilirsiniz. Davet edilen taraflar, dahil edecekleri oyunları/paketleri seçer. Pakete her yeni alt paket eklendiğinde veya indirim yüzdesi değiştiğinde pakete katkıda bulunan herkesin paket yayınlanmadan önce oyunlarının pakete dahil olduğunu onaylaması gerekir.`,
