  Tt = `Valve Corporation`,
  Et = `KONUŞMACILAR HAKKINDA`,
  Dt = `Gautam Babbar - Valve'da Tasarımcı`,
  Ot = `Gautam son 15 yıldır Left 4 Dead, Portal, Half-Life, Counter-Strike, Alien Swarm ve Steam gibi birçok Valve serisi ve ürünleri üzerinde çalıştı. An itibarıyla kendisi CS:GO'ya katkıda bulunuyor.`,
  kt = `Adil Sardar - Valve'da Mühendis`,
  At = `Adil, Steam yazılım geliştirme ekibinin bir parçası. Steam'deki birçok teknoloji üzerinde emeği geçti. An itibarıyla etkinlikleri, indirimleri ve canlı yayınları destekleyecek teknolojiler üzerinde çalışıyor.`,
  jt = `Alden Kroll - Valve'da Tasarımcı`,
  Mt = `Alden Kroll, Valve'da tasarımcı olarak görev yapmaktadır. Son 15 yıldır Valve'da tasarımcılık yapan Alden Team Fortress 2, Portal ve Left 4 Dead gibi oyunlar ve Steam üzerinde çalıştı. Alden an itibarıyla Steam mağazasında ve Steamworks yayıncılık araçları üzerinde tasarım, işletme ve iletişimi birleştirerek bir tasarımcı olarak çalışıyor ve ayrıca geliştiricilerle iletişime geçerek çeşitli organizasyonlar düzenliyor.`,
  Nt = `Jenny Windom - Rose City Games'te İletişim Müdürü`,
  Pt = `Jenny bağımsız oyunlar ve bu oyunların toplulukları, ayrıca endüstri genelinde temsiliyeti artırma konularında oldukça tutkuludur. Şimdiye kadarki görevleri arasında Rose City Games'te (The World Next Door, Floppy Knights, Garden Story) iletişim müdürlüğü, Kowloon Nights'ta iletişim ve kendi başına yaptığı bağımsız oyun tavsiyeleri ve içerik üreticiliği yer alıyor!`,
  Ft = `Joe Tirado - System Era Softworks'te İletişim ve Pazarlama Yöneticisi`,
  It = `Joe bir sanatçı, tasarımcı ve temsiliyet savunucusudur. Joe, System Era Softworks'te 2019 senesinde Webby Awards'ta “Best Adventure Game” (En İyi Macera Oyunu), SXSW Gaming Awards'ta “Gamer’s Voice Award” (Oyuncunun Sesi) ödüllerini kazanan Astroneer'in geliştirici ekibinin bir parçasıydı. Kendisi aynı zamanda oyun endüstrisinde Latin Amerika kökenli kişilerin temsil edildiği ve birbirleriyle iletişime geçebildiği bir platform olan "Latinx in Gaming"in eş kurucularındandır.`,
  Lt = `Steam İletişim Araçlarına Dair`,
  Rt = `Alden Kroll ve Adil Sardar - Valve Corporation`,
  zt = `TSİ 21:00 - 22:02`,
  Bt = `Bu oturumda Steam Duyuru ve Etkinlik sisteminden, özelliği geliştiren kişilerce detaylıca bahsedilecek. Temel özellikleri öğrenin, araçları iş başında görün ve Steam'in iletişim araçlarından en iyi şekilde nasıl faydalanabileceğinizi öğrenin.`,
  Vt = `Güncellemeleriniz Konuşsun`,
  Ht = `Gautam Babbar - Valve Corporation`,
  Ut = `TSİ 20:20–20:47`,
  Wt = `Counter-Strike: Global Offensive'in oldukça büyük bir oyuncu kitlesi var. Gautam yapacağı konuşmada CS:GO ekibinin içerik ve oyun değişikliklerini bu derece geniş bir kitle için nasıl kullandığını anlatacak. Ayrıca bir oyun ekibinin oyuncularla ne zaman konuşması ve ne zaman dinlemesi gerektiğine dair kendi bakış açısını sunacak.`,
  Gt = `Oyuncularla İletişime Geçmek: 1. Kısım`,
  Kt = `Jenny Windom - Rose City Games`,
  qt = `TSİ 22:15 - 22:55`,
  Jt = `Bazen oyuncularla gerçekleştirilen iletişim ve etkinlikler sadece büyük çevrimiçi çok oyunculu oyunlar için iyi bir fikirmiş gibi gelebilir ancak bu konuşmada Jenny bunun böyle olmadığını kanıtlayacak. Bu oturumda iki tane görece küçük tek oyunculu oyunda (Garden Story, Picogram tarafından geliştiriliyor ve yakında çıkacak; Floppy Knights, Rose City Games tarafından geliştirilen bir kart dövüş oyunu) topluluk oluşturmak ve etkileşim sağlamak için kullanılan stratejilerden ve tekniklerden bahsedilecek.`,
  Yt = `Oyuncularla İletişime Geçmek: 2. Kısım`,
  Xt = `Joe Tirado - System Era Softworks`,
  Zt = `TSİ 23:00 - 23:44`,
  Qt = `Astroneer 2016'nın sonlarında ilk olarak Erken Erişim'e çıkmış bir oyundu. Aradan geçen neredeyse beş yıldan sonra oyun hem eski hem yeni oyuncular arasında popülerliğini korumaya devam ediyor. Joe, ufak ekiplerin oyuncuları oyunun erken gelişim sürecine dahil etmek için iletişimi nasıl kullanabileceklerinden ve oyun devam ettiği müddetçe gelecek geri bildirimlerden nasıl yararlanabileceklerinden bahsedecek.`,
