  ln = `Atladığımız bir şey mi var?`,
  un = `Oyun ekleme talebi`,
  dn = `Bu etkinliğe uygun olmayan oyunlar`,
  fn = `Resmî bir Steam temalı festivale veya Next Fest'e katılmak üzere davet edilen oyunların, yukarıda da belirtildiği gibi etkinlik için belirlenen tema ve katılım koşullarına uyması gerekir. Oyunlar, temalı festivaller için aşağıdaki iki önemli testi geçmelidir:`,
  pn = `Next Fest için uygunluk, oyunun Steamworks'te planlanan çıkış tarihine göre belirlenir.`,
  mn = `Yukarıdaki katılım koşullarının tamamını karşıladığını düşündüğünüz bir oyununuz varsa, buradaki yeniden değerlendirme sürecini kullanarak bize oyununuzu incelerken göz ardı etmiş olabileceğimiz unsurları bildirin.`,
