  On = `Not: İtirazlar şu anda sadece bir oyun veya yazılım için yapılabilir.`,
  kn = `Yeniden değerlendirme sürecine başlamak için bir oyun seçin`,
  An = `(Katılım için gereklidir)`,
  jn = `(Tavsiye edilir, etkinliğimizi organize etmek için kullanılır)`,
  Mn = `Oyununuzun şu anda aşağıdaki bölümlerde görünmesi planlanıyor. Oyununuzun listelendiği sekme, aşağıdan seçtiğiniz "Oyun Kategorizasyonu" ile belirlenir ve bölümler, oyununuza uygulanan mağaza etiketlerine göre belirlenir. Etkinlik ön izlemesine bir göz atın ve oyununuzun en iyi hangi bölümlere uyabileceğini tespit edin. (Örneğin, bir point and click macera oyununuz varsa aşağıdaki "Macera" kategorisini seçtiğinizden emin olun ve oyunun mağaza sayfası etiketleri arasında "Point and Click" olduğundan emin olun). Organizasyonda son değişiklikler yapıldığında bunun değişebileceğini aklınızda bulundurun.`,
