  Li = `bir destek talebi gönderin.`,
  Ri = `Bu form aracılığıyla kaydolmanın oyununuzun yaklaşan indirimde öne çıkarılacağını garanti etmeyeceğini unutmayın. Valve, öne çıkarılan oyunları herhangi bir sebeple değiştirme hakkını saklı tutar.`,
