  qa = `İnceleme ekibimiz, %1$s adlı oyununuzun bu etkinliğin katılım koşullarına uymadığına karar verdi.`,
  Ja = `Temalı bir resmî Steam indirimine katılmak üzere davet edilen oyunlar ilgili etkinliğin tema ve katılım koşullarına açıkça uymalıdır. Oyununuzun bu tema ve koşullara uyup uymadığı; oyununuzun mağaza sayfasına eklediğiniz etiketlere, ayrıca mağaza sayfanızdaki tanımında oynanışı nasıl sergilediğinize göre belirlenir.`,
  Ya = `Davet edilecek oyunların listesini oluştururken genellikle aşağıdakilerle eşleşen oyunları ararız:`,
  Xa = `Temayı temsil eden <2>önemli mağaza etiketleri</2>. Oyununuz için belirlenmiş mevcut etiketleri <1>etiketleme sihirbazını</1> ziyaret ederek gözden geçirebilirsiniz.`,
  Za = `<1>Mağaza sayfası açıklaması.</1> Oyun açıklamasının, etkinliğin temasına uygun bir şekilde yapılıp yapılmadığını görmek için fragmana, ekran görüntülerine ve oyunun tanımlanmasına bakıyoruz.`,
  Qa = `İnceleme ekibimiz %1$s oyununu başlangıçta bu etkinlik için değerlendirmeye dâhil etmedi.`,
