  to = `%1$s için yeniden değerlendirme talebi kapatıldı.`,
  no = `%1$s için bir değerlendirme talep edin`,
  ro = `Oyununuzun yukarıdaki katılım koşullarını açıkça karşıladığını düşünüyorsanız, buradaki yeniden değerlendirme sürecini kullanarak bize bildirin. Oyununuzu sadece mağaza sayfanızdaki bilgilere göre inceleyebildiğimizden; fragmanlar, ekran görüntüleri ve etiketler de dâhil olmak üzere mağaza sayfanızı gözden geçirin ve oyununuzun belirlediğimiz temayla net bir şekilde uyumlu olarak gösterildiğinden emin olun.`,
  io = `Yaptığımız inceleme sonrasında, %1$s oyununun bu etkinliğin temasına uyduğunu düşünmüyoruz. Lütfen oyununuzun temasına ve/veya oynanışına daha uygun olabilecek etkinlikler için bizi takipte kalın.`,
