  jO = `Başka bir metin eklenmemelidir (ör. "Yayıncı İndirimi", "Ücretsiz Hafta Sonu", "%90'a Varan İndirimler"). Bu varlığın üst kısmında yer alan yerelleştirilmiş afişte ilgili bağlama yer verilecektir. Tek istisna "Seri İndirimi" metnidir.`,
