  wM = `Ana oyununuzun ve demonuzun farklı ülke kısıtlamaları var. İstek listesi e-postaları sadece hem ana oyuna hem de demoya erişebilen müşterilere gönderilir. Ana oyun: %1$s. Demo: %2$s.`,
