  kM = `Lütfen <1>"Mağaza Sayfasını Düzenle > Özel Ayarlar > İlişkilendirilmiş Demolar"</1> kısmına giderek demonuzu ana oyununuzla ilişkilendirin. Bunu yaptıktan sonra değişiklikleri yayınlamayı unutmayın. Bu adımları tamamladıktan sonra güncellemelerin sisteme geçmesi birkaç dakika sürebilir.`,
