  EN = `Oyuncular hem otomatik hem de manuel kaydetmeleri kullanarak oyunu kaydedebilir ve kaydetme işlemi oyunun herhangi bir noktasında yapılabilir. Oyuncular ilerlemelerini kaybetmeyeceklerini bilmek için bu etiketi görmek isterler.`,
