  FN = `Bazı oyunlar ekranı görmeden oynanabilir. Örneğin bir oyun tamamen ses odaklı olarak tasarlanmış olabilir veya ekran okuyucular ya da seslendirme için yeterli destek sunarak görme engelli kişiler için eksiksiz bir deneyim sağlayabilir.`,
