  VN = `Oyuncuların, duymaları gereken seslere odaklanabilmek için dikkat dağıtan sesleri azaltmaları gerekebilir. Oyununuzda özel ses kontrolleri varsa oyuncular, müzik, ses efektleri, ortam sesleri ve karakter konuşmaları gibi farklı ses türlerinin ses seviyelerini ayarlayabilirler. Tek bir ses seviyesi kaydırıcısı bu ölçütü karşılamaz. Öneriler için <1>Erişilebilirlik Özellikleri Steamworks belgesini</1> inceleyin.`,
