  PP = `Oyun içindeki metin ve sesli sohbet gibi sosyal deneyimler, görme veya işitme kaybı bulunan oyuncular tarafından kullanılamayabilir. Metinden sese çevirme özelliği oyuncuların sohbette yazılanları gerçek zamanlı olarak duymasını sağlarken, sesten metne çevirme özelliği de oyuncuların sesli sohbeti gerçek zamanlı olarak okumalarına olanak tanır. Metinden sese ve sesten metne özelliklerine dair tavsiyelerimiz için <1>Erişilebilirlik Özellikleri Steamworks belgesine</1> göz atın.`,
