  lF = `Girdi aygıtları da dâhil olmak üzere oyununuzun desteklediği VR aygıtlarının, sistem gereksinimlerinde belirtilmesi gerektiğini lütfen aklınızda bulundurun. Burada belirtilen kontrolcü desteği masaüstü veya Geniş Ekran modu desteğini içermelidir.`,
